//! 🧳️ Genuine Drawing retained decision and inverse preparation share immutable command and base sources.
use crate::{retained_drag::DrawingOriginalDrag,DrawingMutation,retained_decision::DrawingOriginalFieldDecision,retained_inverse::DrawingOriginalFieldInverse};
use semio_s_artifact_draw_drawing_model::snapshot::DrawingSnapshot;
use semio_s_artifact_draw_drawing_diff::DrawingDiff;
use protocol::{RetainedMutation,RetainedMutationPreparation,RetainedMutationDecision,RetainedMutationAdvance,RetainedMutationCloseContext,RetainedDiagnosticPreparation,RetainedDiagnosticSpec,MutationMessage,MutationMessageLedgerRetirement};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedCloneClose,retained_clone_grant_admits}};
use semio_framework_value::factory::vector::FactoryVectorRetirement;
use std::mem::{ManuallyDrop,size_of};
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"Drawing original semantic output is not retained")}
fn fixed(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}
pub struct DrawingRetainedPreparation{drag:DrawingOriginalDrag,diagnostic:RetainedDiagnosticPreparation<0>,messages:ManuallyDrop<Option<Vec<MutationMessage>>>,ledger:ManuallyDrop<Option<MutationMessageLedgerRetirement>>,reason:Option<&'static str>,unchanged:bool,decision_phase:u8,decision:DrawingOriginalFieldDecision,inverse:DrawingOriginalFieldInverse,output:ManuallyDrop<Option<DrawingDiff>>,rows:ManuallyDrop<Option<Vec<DrawingMutation>>>,retirement:RetainedCloneClose,row_close:Option<FactoryVectorRetirement<DrawingMutation>>,decision_done:bool,inverse_done:bool,closing:bool}
impl RetainedMutation<DrawingSnapshot> for DrawingMutation{type Preparation=DrawingRetainedPreparation;}
impl RetainedMutationPreparation<DrawingSnapshot,DrawingMutation> for DrawingRetainedPreparation{
 fn new()->Self{Self{drag:Default::default(),diagnostic:Default::default(),messages:ManuallyDrop::new(None),ledger:ManuallyDrop::new(None),reason:None,unchanged:false,decision_phase:0,decision:Default::default(),inverse:Default::default(),output:ManuallyDrop::new(None),rows:ManuallyDrop::new(None),retirement:Default::default(),row_close:None,decision_done:false,inverse_done:false,closing:false}}
 fn decision_demand(&self,m:RetainedCloneRef<'_,DrawingMutation>,b:RetainedCloneRef<'_,DrawingSnapshot>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.decision_done{return Err(invalid())}Ok(match self.decision_phase{0=>if matches!(m.get(),DrawingMutation::DragLayers(_)){if self.drag.ready(){let mut d=self.drag.take_decision_demand()?;d.copy_bytes+=2*size_of::<Option<DrawingDiff>>()+2*size_of::<Option<Vec<MutationMessage>>>()+64;d}else{self.drag.demand(b,m,body)?}}else if matches!(m.get(),DrawingMutation::SetArtboard(_)){fixed(2*size_of::<DrawingDiff>()+2*size_of::<Option<semio_s_artifact_draw_drawing_model::DrawingArtboard>>()+256)}else if self.decision.ready(){let mut d=self.decision.take_demand()?;d.copy_bytes+=2*size_of::<Option<DrawingDiff>>()+size_of::<bool>()*2+size_of::<Option<&'static str>>();d}else{self.decision.demand(b,m,body)?},1=>RetainedDiagnosticPreparation::<0>::start_demand(),2=>self.diagnostic.demand([],body)?,3=>fixed(3*size_of::<Vec<MutationMessage>>()+size_of::<bool>()),_=>return Err(invalid())})}
 fn decide(&mut self,m:RetainedCloneRef<'_,DrawingMutation>,b:RetainedCloneRef<'_,DrawingSnapshot>,body:usize,g:RetainedCloneGrant)->Result<RetainedMutationAdvance,ValueError>{let d=self.decision_demand(m,b,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedMutationAdvance::Progress(Default::default()))}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};match self.decision_phase{
  0=>if matches!(m.get(),DrawingMutation::DragLayers(_)){if self.drag.ready(){let(reason,unchanged)=self.drag.outcome();let(output,messages,q)=self.drag.take_decision(g)?;*self.output=output;*self.messages=Some(messages);self.reason=reason;self.unchanged=unchanged;self.decision_done=true;p=q;p.copied_bytes=d.copy_bytes;return Ok(RetainedMutationAdvance::Ready(p))}else{p=self.drag.advance(b,m,body,g)?.progress()}}else if let DrawingMutation::SetArtboard(v)=m.get(){self.reason=(!crate::artboard::valid(&v.artboard)).then_some("mutation.invariant");self.unchanged=v.artboard==b.get().artboard;if self.reason.is_none(){*self.output=Some(if self.unchanged{DrawingDiff::default()}else{DrawingDiff{artboard:Some(crate::artboard::copy(&v.artboard)),..Default::default()}})}if self.reason.is_some()||self.unchanged{self.decision_phase=1}else{self.decision_done=true;return Ok(RetainedMutationAdvance::Ready(p))}}else if self.decision.ready(){let(reason,unchanged)=self.decision.outcome();let(v,q)=self.decision.take(g)?;*self.output=v;self.reason=reason;self.unchanged=unchanged;p=q;p.copied_bytes=d.copy_bytes;if reason.is_some()||unchanged&&!matches!(m.get(),DrawingMutation::UpdatePathGeometry(_)|DrawingMutation::UpdateText(_)|DrawingMutation::UpdateImage(_)|DrawingMutation::SetShapeCoordinate(_)){self.decision_phase=1}else{self.decision_done=true;return Ok(RetainedMutationAdvance::Ready(p))}}else{p=self.decision.advance(b,m,body,g)?.progress()},
  1=>{let(level,code,message)=if let Some(code)=self.reason{(if code=="mutation.invariant"{semio_framework_diagnostic::Severity::Fatal}else{semio_framework_diagnostic::Severity::Error},code,"The Drawing command requires an admissible original target and native field value.")}else{(semio_framework_diagnostic::Severity::Warning,"mutation.no-op","The original Drawing field already has the authored value.")};p=self.diagnostic.start(RetainedDiagnosticSpec{level,code,message},g)?;self.decision_phase=2},
  2=>{let s=self.diagnostic.advance([],body,g)?;p=s.progress();if matches!(s,RetainedCloneStep::Complete(_)){self.decision_phase=3}},
  3=>{let(rows,q)=self.diagnostic.take(g)?.ok_or_else(invalid)?;*self.messages=Some(rows);self.decision_done=true;p=q;p.copied_bytes=d.copy_bytes;return Ok(RetainedMutationAdvance::Ready(p))},_=>return Err(invalid())}Ok(RetainedMutationAdvance::Progress(p))}
 fn take_decision(&mut self)->RetainedMutationDecision<DrawingDiff>{let messages=self.messages.take().unwrap_or_default();if self.reason.is_some(){RetainedMutationDecision::Refused(messages)}else{RetainedMutationDecision::Admitted(self.output.take().expect("funded original Drawing decision"),messages)}}
 fn inverse_demand(&self,m:RetainedCloneRef<'_,DrawingMutation>,b:RetainedCloneRef<'_,DrawingSnapshot>,_:RetainedCloneRef<'_,DrawingDiff>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.inverse_done{return Err(invalid())}if matches!(m.get(),DrawingMutation::DragLayers(_)){let mut d=self.drag.take_inverse_demand()?;d.copy_bytes+=2*size_of::<Option<Vec<DrawingMutation>>>()+size_of::<bool>();return Ok(d)}if self.unchanged{return Ok(fixed(2*size_of::<Option<Vec<DrawingMutation>>>()+size_of::<bool>()))}if matches!(m.get(),DrawingMutation::SetArtboard(_)){return Ok(RetirementDemand{capacity_bytes:size_of::<DrawingMutation>(),..fixed(2*size_of::<DrawingMutation>()+2*size_of::<Vec<DrawingMutation>>()+256)})}if self.inverse.ready(){let mut d=self.inverse.take_demand()?;d.copy_bytes+=2*size_of::<Option<Vec<DrawingMutation>>>()+size_of::<bool>();Ok(d)}else{self.inverse.demand(b,m,body)}}
 fn inverse(&mut self,m:RetainedCloneRef<'_,DrawingMutation>,b:RetainedCloneRef<'_,DrawingSnapshot>,diff:RetainedCloneRef<'_,DrawingDiff>,body:usize,g:RetainedCloneGrant)->Result<RetainedMutationAdvance,ValueError>{let d=self.inverse_demand(m,b,diff,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedMutationAdvance::Progress(Default::default()))}if matches!(m.get(),DrawingMutation::DragLayers(_)){let(rows,mut p)=self.drag.take_inverse(g)?;*self.rows=Some(rows.ok_or_else(invalid)?);self.inverse_done=true;p.copied_bytes=d.copy_bytes;return Ok(RetainedMutationAdvance::Ready(p))}if self.unchanged{*self.rows=Some(Vec::new());self.inverse_done=true;return Ok(RetainedMutationAdvance::Ready(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}if matches!(m.get(),DrawingMutation::SetArtboard(_)){*self.rows=Some(Vec::new());let rows=self.rows.as_mut().unwrap();let allocated=rows.try_reserve_exact(1);let p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:rows.capacity()*size_of::<DrawingMutation>(),..Default::default()};if allocated.is_err()||!p.fits(g){return Err(invalid().with_retained_progress(p))}rows.push(crate::artboard::set_artboard(crate::artboard::copy(&b.get().artboard)));self.inverse_done=true;return Ok(RetainedMutationAdvance::Ready(p))}if self.inverse.ready(){let(v,mut p)=self.inverse.take(g)?;*self.rows=Some(v.ok_or_else(invalid)?);self.inverse_done=true;p.copied_bytes=d.copy_bytes;return Ok(RetainedMutationAdvance::Ready(p))}let step=self.inverse.advance(b,m,body,g)?;Ok(RetainedMutationAdvance::Progress(step.progress()))}
 fn take_inverse(&mut self)->Vec<DrawingMutation>{self.rows.take().expect("funded original Drawing inverse")}
 fn begin_close(&mut self){self.closing=true;self.drag.begin_close();self.diagnostic.begin_close();self.decision.begin_close();self.inverse.begin_close();}
 fn close_demand(&self,c:RetainedMutationCloseContext<'_,DrawingMutation>,body:usize)->Result<RetirementDemand,ValueError>{if !self.diagnostic.terminal_is_empty(){return self.diagnostic.close_demand(body)}if let Some(l)=self.ledger.as_ref(){return semio_framework_value::ErasedSnapshotRetirement::next_demand(l,body)}if self.messages.is_some(){return Ok(fixed(size_of::<MutationMessageLedgerRetirement>()+2*size_of::<Vec<MutationMessage>>()))}if !self.drag.terminal_is_empty(){return self.drag.close_demand(c,body)}if !self.decision.terminal_is_empty(){return self.decision.close_demand(body)}if !self.inverse.terminal_is_empty(){return self.inverse.close_demand(c,body)}if !self.retirement.is_empty()||self.output.is_some(){return self.retirement.next_owner_demands::<DrawingDiff>(self.output.is_some(),&None,body)}if let Some(r)=self.row_close.as_ref(){return if r.terminal_is_empty(){Ok(fixed(2*size_of::<Option<FactoryVectorRetirement<DrawingMutation>>>()))}else{r.demands(c.mutations,body)}}if self.rows.is_some(){return Ok(FactoryVectorRetirement::<DrawingMutation>::constructor_demand())}Ok(Default::default())}
 fn close_step(&mut self,c:RetainedMutationCloseContext<'_,DrawingMutation>,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(invalid())}let d=self.close_demand(c,g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.diagnostic.terminal_is_empty(){return self.diagnostic.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if let Some(l)=self.ledger.as_mut(){let s=l.close_step(g)?;if l.terminal_is_empty(){self.ledger.take();}return Ok(RetainedCloneStep::Progress(s.progress()))}if let Some(rows)=self.messages.take(){*self.ledger=Some(MutationMessageLedgerRetirement::new(String::new(),rows));return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}if !self.drag.terminal_is_empty(){return self.drag.close_step(c,g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.decision.terminal_is_empty(){return self.decision.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.inverse.terminal_is_empty(){return self.inverse.close_step(c,g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.retirement.is_empty(){return self.retirement.step_granted(g)}if let Some(s)=self.retirement.begin_granted(&mut self.output,g)?{return Ok(s)}if let Some(r)=self.row_close.as_mut(){if r.terminal_is_empty(){self.row_close=None;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}return r.close_step(c.mutations,g)}if let Some(rows)=self.rows.take(){return match FactoryVectorRetirement::admit(rows,g){Ok((r,p))=>{self.row_close=Some(r);Ok(RetainedCloneStep::Progress(p))},Err((e,rows))=>{*self.rows=Some(rows);Err(e)}}}Ok(RetainedCloneStep::Complete(Default::default()))}
 fn terminal_is_empty(&self)->bool{self.closing&&self.drag.terminal_is_empty()&&self.diagnostic.terminal_is_empty()&&self.messages.is_none()&&self.ledger.is_none()&&self.decision.terminal_is_empty()&&self.inverse.terminal_is_empty()&&self.output.is_none()&&self.rows.is_none()&&self.row_close.is_none()&&self.retirement.is_empty()}
}
impl Drop for DrawingRetainedPreparation{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Drawing original semantic preparation requires exact issuer closure");}}
